from __future__ import annotations
import copy
import json
from PySide6.QtCore import Qt
from PySide6.QtWidgets import (
    QApplication, QDialog, QDialogButtonBox, QHBoxLayout, QLabel, QPushButton,
    QTabWidget, QTableWidget, QTableWidgetItem, QVBoxLayout, QWidget,
)
from .model import validate
from .load_manager import LoadCaseCombinationDialog
from .sections import starter_sections

FIELDS = {
    "nodes": ["id", "x", "z", "support", "springs"],
    "members": ["id", "i", "j", "type", "material", "section", "release_i", "release_j"],
    "materials": ["id", "E", "rho"],
    "sections": ["id", "A", "Iz", "kind"],
    "point_loads": ["node", "member", "direction", "value", "x", "case"],
    "distributed_loads": ["member", "direction", "w1", "w2", "x1", "x2", "case"],
}
NUMERIC = {"x", "z", "E", "rho", "A", "Iz", "value", "w1", "w2", "x1", "x2"}
BOOLS = {"release_i", "release_j"}
JSON_FIELDS = {"springs"}


class ModelEditor(QDialog):
    def __init__(self, model, parent=None):
        super().__init__(parent)
        self.setWindowTitle("GO 2D Structural model — m, kN")
        self.resize(980, 680)
        self.data = copy.deepcopy(model)
        self.tables = {}
        root = QVBoxLayout(self)
        note = QLabel("XZ plane · +Z up · E [kN/m²] · A [m²] · Iz [m⁴] · rho [kN/m³] · springs JSON e.g. {\"UZ\":10000}")
        note.setText(note.text() + "\nMoment release_i / release_j: checked = moment hinge, unchecked = rigid.\nNominal GO Core steel properties must be verified before engineering design.")
        note.setWordWrap(True)
        root.addWidget(note)
        tabs = QTabWidget()
        self.tabs = tabs
        root.addWidget(tabs, 1)
        for key, fields in FIELDS.items():
            page = QWidget()
            box = QVBoxLayout(page)
            table = QTableWidget(0, len(fields))
            table.setHorizontalHeaderLabels(fields)
            self.tables[key] = table
            box.addWidget(table, 1)
            controls = QHBoxLayout()
            add = QPushButton("Add")
            duplicate = QPushButton("Duplicate")
            copy_btn = QPushButton("Copy")
            paste_btn = QPushButton("Paste")
            remove = QPushButton("Delete")
            for button in (add, duplicate, copy_btn, paste_btn, remove):
                controls.addWidget(button)
            controls.addStretch()
            box.addLayout(controls)
            add.clicked.connect(lambda _=False, k=key: self.add_row(k, {}))
            duplicate.clicked.connect(lambda _=False, k=key, t=table: self.duplicate_selected(k, t))
            copy_btn.clicked.connect(lambda _=False, t=table: self.copy_selected(t))
            paste_btn.clicked.connect(lambda _=False, k=key, t=table: self.paste_rows(k, t))
            remove.clicked.connect(lambda _=False, t=table: self.remove_selected(t))
            table.setToolTip("Double-click a cell to edit. Copy/Paste uses tab-separated rows compatible with Excel / Google Sheets.")
            for row in self.data.get(key, []):
                self.add_row(key, row)
            tabs.addTab(page, key.replace("_", " ").title())
        section_tools = QHBoxLayout()
        add_sections = QPushButton("Add starter RC / RHS sections")
        add_sections.clicked.connect(self.add_starter_sections)
        section_tools.addWidget(add_sections)
        section_tools.addStretch()
        root.addLayout(section_tools)
        load_case_tools = QHBoxLayout()
        self.load_case_button = QPushButton("Load Cases / Combinations…")
        self.load_case_summary = QLabel()
        self.load_case_summary.setWordWrap(True)
        load_case_tools.addWidget(self.load_case_button)
        load_case_tools.addWidget(self.load_case_summary, 1)
        root.addLayout(load_case_tools)
        self.load_case_button.clicked.connect(self.edit_load_cases)
        self._update_load_case_summary()
        self.error = QLabel()
        self.error.setWordWrap(True)
        root.addWidget(self.error)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(self.accept_model)
        buttons.rejected.connect(self.reject)
        root.addWidget(buttons)

    def add_row(self, key, row):
        table = self.tables[key]
        i = table.rowCount()
        table.insertRow(i)
        for j, field in enumerate(FIELDS[key]):
            value = row.get(field, "")
            if field in BOOLS:
                item = QTableWidgetItem("")
                item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable)
                checked = value is True or str(value).strip().lower() in ("1", "true", "yes", "y")
                item.setCheckState(Qt.CheckState.Checked if checked else Qt.CheckState.Unchecked)
                item.setToolTip("Checked = moment release (hinged end, M=0)")
            else:
                if isinstance(value, (dict, list)):
                    value = json.dumps(value, separators=(",", ":"))
                item = QTableWidgetItem(str(value) if value != "" else "")
            table.setItem(i, j, item)


    def _selected_rows(self, table):
        rows = sorted({index.row() for index in table.selectedIndexes()})
        if not rows and table.currentRow() >= 0:
            rows = [table.currentRow()]
        return rows

    def copy_selected(self, table):
        field_names = next((FIELDS[key] for key, candidate in self.tables.items()
                            if candidate is table), [])
        rows = self._selected_rows(table)
        if not rows:
            return
        lines = []
        for r in rows:
            values = []
            for c in range(table.columnCount()):
                item = table.item(r, c)
                if item and c < len(field_names) and field_names[c] in BOOLS:
                    values.append("true" if item.checkState() == Qt.CheckState.Checked else "false")
                else:
                    values.append(item.text() if item else "")
            lines.append("\t".join(values))
        QApplication.clipboard().setText("\n".join(lines))

    def duplicate_selected(self, key, table):
        rows = self._selected_rows(table)
        existing_ids = {
            (table.item(i, 0).text().strip() if table.item(i, 0) else "")
            for i in range(table.rowCount())
        } if FIELDS[key] and FIELDS[key][0] == "id" else set()
        for r in rows:
            row = {}
            for c, field in enumerate(FIELDS[key]):
                item = table.item(r, c)
                text = item.text().strip() if item else ""
                if field in BOOLS and item:
                    row[field] = item.checkState() == Qt.CheckState.Checked
                elif text:
                    row[field] = text
            if "id" in row:
                base = row["id"] + "_copy"
                candidate = base
                n = 2
                while candidate in existing_ids:
                    candidate = f"{base}{n}"; n += 1
                row["id"] = candidate
                existing_ids.add(candidate)
            self.add_row(key, row)

    def paste_rows(self, key, table):
        text = QApplication.clipboard().text().strip("\r\n")
        if not text:
            return
        start = table.currentRow()
        if start < 0:
            start = table.rowCount()
        rows = [line.split("\t") for line in text.replace("\r\n", "\n").split("\n") if line.strip()]
        for offset, values in enumerate(rows):
            target = start + offset
            if target >= table.rowCount():
                table.insertRow(target)
            for c in range(min(len(values), len(FIELDS[key]))):
                if FIELDS[key][c] in BOOLS:
                    item = QTableWidgetItem("")
                    item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable)
                    item.setCheckState(Qt.CheckState.Checked if values[c].strip().lower() in
                                       ("true", "1", "yes", "y") else Qt.CheckState.Unchecked)
                else:
                    item = QTableWidgetItem(values[c])
                table.setItem(target, c, item)

    def remove_selected(self, table):
        rows = sorted({index.row() for index in table.selectedIndexes()}, reverse=True)
        for row in rows:
            table.removeRow(row)

    def add_starter_sections(self):
        existing = {self.tables["sections"].item(i, 0).text().strip() for i in range(self.tables["sections"].rowCount()) if self.tables["sections"].item(i, 0)}
        for row in starter_sections():
            if row["id"] not in existing:
                self.add_row("sections", row)


    def _update_load_case_summary(self):
        cases = ", ".join(self.data.get("cases", [])) or "—"
        combinations = ", ".join((self.data.get("combinations", {}) or {}).keys()) or "—"
        sw = "OFF"
        if self.data.get("self_weight"):
            sw = "ON → " + str(self.data.get("self_weight_case") or "—")
        self.load_case_summary.setText(f"Cases: {cases}  ·  Combinations: {combinations}  ·  Self-weight: {sw}")

    def edit_load_cases(self):
        try:
            base = self._collect_tables_only()
        except Exception as exc:
            self.error.setText(str(exc))
            return
        dialog = LoadCaseCombinationDialog(base, self)
        if dialog.exec():
            self.data = dialog.data
            self._update_load_case_summary()

    def _collect_tables_only(self):
        out = copy.deepcopy(self.data)
        for key, fields in FIELDS.items():
            rows = []
            table = self.tables[key]
            for i in range(table.rowCount()):
                row = {}
                for j, field in enumerate(fields):
                    item = table.item(i, j)
                    text = item.text().strip() if item else ""
                    if field in BOOLS and item:
                        row[field] = item.checkState() == Qt.CheckState.Checked
                        continue
                    if not text:
                        continue
                    if field in NUMERIC:
                        row[field] = float(text)
                    elif field in BOOLS:
                        row[field] = text.lower() in ("1", "true", "yes", "y")
                    elif field in JSON_FIELDS:
                        row[field] = json.loads(text)
                    else:
                        row[field] = text
                if row:
                    rows.append(row)
            out[key] = rows
        return out

    def _collect(self):
        out = copy.deepcopy(self.data)
        for key, fields in FIELDS.items():
            rows = []
            table = self.tables[key]
            for i in range(table.rowCount()):
                row = {}
                for j, field in enumerate(fields):
                    item = table.item(i, j)
                    text = item.text().strip() if item else ""
                    if field in BOOLS and item:
                        row[field] = item.checkState() == Qt.CheckState.Checked
                        continue
                    if not text:
                        continue
                    if field in NUMERIC:
                        row[field] = float(text)
                    elif field in BOOLS:
                        row[field] = text.lower() in ("1", "true", "yes", "y")
                    elif field in JSON_FIELDS:
                        row[field] = json.loads(text)
                    else:
                        row[field] = text
                if row:
                    rows.append(row)
            out[key] = rows
        out["cases"] = copy.deepcopy(self.data.get("cases", []))
        out["case_metadata"] = copy.deepcopy(self.data.get("case_metadata", {}))
        out["combinations"] = copy.deepcopy(self.data.get("combinations", {}))
        out["combination_metadata"] = copy.deepcopy(self.data.get("combination_metadata", {}))
        out["self_weight"] = bool(self.data.get("self_weight", False))
        out["self_weight_case"] = self.data.get("self_weight_case")
        out.setdefault("schema", 1)
        out.setdefault("version", 4)
        return validate(out)

    def accept_model(self):
        try:
            self.data = self._collect()
        except Exception as exc:
            self.error.setText(str(exc))
            return
        self.accept()


class ResultTableDialog(QDialog):
    def __init__(self, model, result, case, parent=None):
        super().__init__(parent)
        self.setWindowTitle("GO 2D Structural results — " + case)
        self.resize(920, 600)
        root = QVBoxLayout(self)
        tabs = QTabWidget()
        root.addWidget(tabs, 1)
        nodes = QTableWidget(0, 7)
        nodes.setHorizontalHeaderLabels(["Node", "UX", "UZ", "Rot", "RX", "RZ", "MY"])
        for nid, row in result["cases"][case]["nodes"].items():
            i = nodes.rowCount(); nodes.insertRow(i)
            values = [nid, row["ux"], row["uz"], row["rotation"], row["Rx"], row["Rz"], row["My"]]
            for j, value in enumerate(values): nodes.setItem(i, j, QTableWidgetItem(f"{value:.8g}" if isinstance(value, float) else str(value)))
        tabs.addTab(nodes, "Nodes / Reactions")
        members = QTableWidget(0, 8)
        members.setHorizontalHeaderLabels(["Member", "Quantity", "Type", "Value", "x", "Side", "Unit", "L"])
        units = {"N": "kN", "V": "kN", "M": "kN.m", "d": "m"}
        for mid, member in result["cases"][case]["members"].items():
            for quantity, extrema in member["extrema"].items():
                for kind, row in extrema.items():
                    i = members.rowCount(); members.insertRow(i)
                    values = [mid, quantity, kind, row["value"], row["x"], row["side"], units[quantity], member["L"]]
                    for j, value in enumerate(values): members.setItem(i, j, QTableWidgetItem(f"{value:.8g}" if isinstance(value, float) else str(value)))
        tabs.addTab(members, "Member extrema")
        close = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        close.rejected.connect(self.reject); close.accepted.connect(self.accept)
        root.addWidget(close)

"""GO Engineering Core v0.1: shared read-only, nominal steel section properties.

This module and steel_sections_v1.json are *byte-identical vendored snapshots* in
GO Factory and GO anaStruct. The catalog is a transport format, not a design
approval. Do not couple this file to IngeTrazo, Qt, anaStruct or a 3D engine.
"""
from __future__ import annotations

import copy
import hashlib
from functools import lru_cache
import json
import math
from pathlib import Path

SCHEMA = "go-steel-sections/1"
CATALOG_VERSION = "0.1.0"
STATUS_NOMINAL = "NOMINAL_GEOMETRY_ONLY"
STATUS_UNSUPPORTED = "NO_FEM_PROPERTIES"


class CatalogError(ValueError):
    pass


@lru_cache(maxsize=1)
def _load_catalog():
    filename = Path(__file__).with_name("steel_sections_v1.json")
    raw = json.loads(filename.read_text(encoding="utf-8"))
    if raw.get("schema") != SCHEMA or raw.get("catalog_version") != CATALOG_VERSION:
        raise CatalogError("Unsupported GO Steel Catalog schema or version")
    sections = raw.get("sections")
    if not isinstance(sections, dict) or not sections:
        raise CatalogError("GO Steel Catalog has no sections")
    for key, row in sections.items():
        if not isinstance(key, str) or not isinstance(row, dict):
            raise CatalogError("GO Steel Catalog entry is invalid")
        for field in ("h_m", "b_m", "tw_m", "tf_m", "t_m", "legacy_weight_kg_m"):
            v = row.get(field)
            if isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or v < 0:
                raise CatalogError(f"{key}.{field}: invalid nominal dimension/weight")
    return raw


@lru_cache(maxsize=1)
def catalog_sha256():
    return hashlib.sha256(Path(__file__).with_name("steel_sections_v1.json").read_bytes()).hexdigest()


def catalog_info():
    doc = _load_catalog()
    return {
        "schema": doc["schema"], "version": doc["catalog_version"],
        "sha256": catalog_sha256(),
        "source": doc["source"], "count": len(doc["sections"]),
        "nominal_count": sum(row["analysis_status"] == STATUS_NOMINAL
                             for row in doc["sections"].values()),
    }


def section_names():
    return list(_load_catalog()["sections"])


def section_record(section_id):
    row = _load_catalog()["sections"].get(section_id)
    if row is None:
        raise CatalogError(f"Unknown GO Steel Catalog section: {section_id}")
    return copy.deepcopy({"id": section_id, **row, "catalog_version": CATALOG_VERSION})


def nominal_section_properties(section_id, *, axis, acknowledge_unverified=False):
    """Return A and strong/weak I for simple idealized profiles in SI units.

    Requires two explicit decisions: axis AND consent to use approximate
    unverified nominal geometry. Radius, fillets, actual rolling tolerances
    and net-section reductions are not accounted for. For H/WF flanges are
    ideal rectangles; RHS/SHS corners are ideal right angles.
    """
    if axis not in ("strong", "weak"):
        raise CatalogError("Select an explicit section bending axis: strong/weak")
    if acknowledge_unverified is not True:
        raise CatalogError("Section properties are nominal/unverified; explicit preview acceptance required")
    s = section_record(section_id)
    if s["analysis_status"] != STATUS_NOMINAL:
        raise CatalogError(
            f"{section_id} ({s['family']}) has no defensible v0.1 FEM properties; "
            "an independently verified engineering section is required"
        )
    h, b, tw, tf, t = (s[k] for k in ("h_m", "b_m", "tw_m", "tf_m", "t_m"))
    if s["family"] == "H":
        if min(h, b, tw, tf) <= 0 or 2 * tf >= h or tw >= b:
            raise CatalogError(f"{section_id}: invalid ideal H geometry")
        web_h = h - 2 * tf
        area = 2 * b * tf + web_h * tw
        strong = 2 * ((b * tf**3) / 12 + (b * tf) * ((h - tf) / 2)**2) + tw * web_h**3 / 12
        weak = 2 * tf * b**3 / 12 + web_h * tw**3 / 12
    elif s["family"] in ("RHS", "SHS"):
        if min(h, b, t) <= 0 or 2 * t >= min(h, b):
            raise CatalogError(f"{section_id}: invalid ideal hollow rectangle")
        hi, bi = h - 2*t, b - 2*t
        area = b*h - bi*hi
        strong = (b*h**3 - bi*hi**3)/12
        weak = (h*b**3 - hi*bi**3)/12
    elif s["family"] == "PIPE":
        if b <= 0 or t <= 0 or 2*t >= b:
            raise CatalogError(f"{section_id}: invalid ideal circular hollow geometry")
        d, di = b, b - 2*t
        area = math.pi * (d*d - di*di)/4
        strong = weak = math.pi * (d**4 - di**4)/64
    else:
        raise CatalogError(f"Unsupported nominal family {s['family']}")
    if not all(math.isfinite(v) and v > 0 for v in (area, strong, weak)):
        raise CatalogError(f"{section_id}: invalid derived nominal properties")
    # Rough mass calculated at 7850 kg/m3 for diagnostic comparison only.
    mass_est = area * 7850.0
    source_mass = s["legacy_weight_kg_m"]
    diff = None if source_mass <= 0 else 100.0 * (mass_est - source_mass) / source_mass
    return {
        "section_id": section_id, "catalog_version": CATALOG_VERSION,
        "family": s["family"], "axis": axis, "A_m2": area,
        "Ix_m4": strong, "Iy_m4": weak,
        "Iz_m4": strong if axis == "strong" else weak,
        "nominal_mass_kg_m": mass_est,
        "legacy_approx_mass_kg_m": source_mass,
        "mass_difference_pct": diff,
        "status": STATUS_NOMINAL, "verified": False,
        "warning": "Approximate idealized geometry only; not verified for engineering design",
    }


def section_identity(section_id):
    """Metadata for geometry/BOQ; deliberately no FEM A/I without explicit axis."""
    rec = section_record(section_id)
    return {
        "section_catalog_id": rec["id"],
        "section_catalog_version": CATALOG_VERSION,
        "section_catalog_sha256": catalog_sha256(),
        "section_property_status": rec["analysis_status"],
        "section_legacy_mass_status": "APPROXIMATE_UNVERIFIED",
    }

from __future__ import annotations
import csv
import math
from pathlib import Path



def _case_color(model, case_name, *, self_weight=False):
    metadata = (model.get("case_metadata", {}) or {}).get(case_name, {})
    load_type = str(metadata.get("type", "")).strip().lower()
    name = str(case_name or "").strip().upper()
    if self_weight:
        return "#6b7280"
    if load_type == "dead" or name.startswith("DL") or name in ("SW", "G"):
        return "#6b7280"
    if load_type == "live" or name.startswith("LL") or name.startswith("L"):
        return "#2563eb"
    if load_type == "wind" or name.startswith("WL") or name.startswith("W"):
        return "#16a34a"
    if load_type in ("seismic", "earthquake") or name.startswith("EQ"):
        return "#dc2626"
    if load_type in ("thermal", "temperature") or name.startswith("TEMP") or name.startswith("T"):
        return "#9333ea"
    palette = ["#0f766e", "#b45309", "#7c3aed", "#be123c", "#0369a1", "#15803d"]
    return palette[sum(ord(ch) for ch in name) % len(palette)]


def _case_factor(model, selected_case, load_case):
    if selected_case in model.get("cases", []):
        return 1.0 if selected_case == load_case else 0.0
    return float((model.get("combinations", {}).get(selected_case, {}) or {}).get(load_case, 0.0))


def _visible_legend_entries(model, selected_case, active_only=True, options=None):
    if active_only:
        if selected_case in model.get("cases", []):
            visible = {selected_case: 1.0}
        else:
            visible = {
                name: float(factor)
                for name, factor in (model.get("combinations", {}).get(selected_case, {}) or {}).items()
                if abs(float(factor)) > 1e-14
            }
    else:
        visible = {name: 1.0 for name in model.get("cases", [])}
    options = options or {}
    show_point = bool(options.get("show_point_loads", True))
    show_dist = bool(options.get("show_distributed_loads", True))
    show_sw = bool(options.get("show_self_weight", True))
    visible_load_cases = set()
    if show_point:
        visible_load_cases.update(row.get("case") for row in model.get("point_loads", []) if row.get("case"))
    if show_dist:
        visible_load_cases.update(row.get("case") for row in model.get("distributed_loads", []) if row.get("case"))
    sw_case = model.get("self_weight_case") or "SW"
    if model.get("self_weight") and show_sw:
        visible_load_cases.add(sw_case)

    entries = []
    for case_name in model.get("cases", []):
        if case_name not in visible or case_name not in visible_load_cases:
            continue
        meta = (model.get("case_metadata", {}) or {}).get(case_name, {})
        entries.append({
            "name": case_name,
            "type": str(meta.get("type") or case_name),
            "description": str(meta.get("description", "")).strip(),
            "factor": float(visible.get(case_name, 1.0)),
            "color": _case_color(model, case_name),
        })
    sw_case = model.get("self_weight_case") or "SW"
    if model.get("self_weight") and show_sw and sw_case in visible:
        entries.append({
            "name": sw_case, "type": "Self-weight", "description": "Automatic gravity load",
            "factor": float(visible.get(sw_case, 1.0)), "color": _case_color(model, sw_case, self_weight=True),
        })
    return entries


def _draw_load_legend(painter, model, selected_case, rect, active_only=True, options=None):
    from PySide6.QtCore import QPointF, QRectF, Qt
    from PySide6.QtGui import QBrush, QColor, QFont, QPen
    entries = _visible_legend_entries(model, selected_case, active_only, options=options)
    painter.setPen(QPen(QColor("#1f2933"), 1))
    font = QFont(painter.font()); font.setPointSize(8); painter.setFont(font)
    x = rect.left(); y = rect.top()
    painter.drawText(QRectF(x, y, rect.width(), 16), Qt.AlignmentFlag.AlignLeft, "Load legend")
    y += 18
    for entry in entries:
        painter.setPen(QPen(QColor(entry["color"]), 1)); painter.setBrush(QBrush(QColor(entry["color"])))
        painter.drawEllipse(QPointF(x + 5, y + 5), 4, 4)
        painter.setPen(QPen(QColor("#1f2933"), 1))
        factor = entry["factor"]
        factor_text = "" if abs(factor - 1.0) < 1e-12 else f" x{factor:.3g}"
        label = f"{entry['name']} - {entry['type']}{factor_text}"
        if entry["description"]:
            label += f" ({entry['description']})"
        painter.drawText(QRectF(x + 16, y - 3, rect.width() - 16, 16), Qt.AlignmentFlag.AlignLeft, label)
        y += 16
        if y > rect.bottom() - 14:
            break


def _fit_image_rect(image, target):
    from PySide6.QtCore import QRectF
    if image is None or image.isNull() or image.width() <= 0 or image.height() <= 0:
        return target
    scale = min(target.width() / image.width(), target.height() / image.height())
    width = image.width() * scale
    height = image.height() * scale
    return QRectF(target.center().x() - width / 2.0, target.center().y() - height / 2.0, width, height)


def export_csv(directory, model, result, case):
    root = Path(directory)
    root.mkdir(parents=True, exist_ok=True)
    data = result["cases"][case]
    paths = []

    def write(name, header, rows):
        path = root / name
        with path.open("w", encoding="utf-8-sig", newline="") as stream:
            writer = csv.writer(stream)
            writer.writerow(header)
            writer.writerows(rows)
        paths.append(str(path))

    write(
        "model_nodes.csv",
        ["Node", "X [m]", "Z [m]", "Support", "Springs"],
        [[n["id"], n["x"], n["z"], n.get("support", "Free"), n.get("springs", {})] for n in model["nodes"]],
    )
    write(
        "model_members.csv",
        ["Member", "i", "j", "Type", "Material", "Section", "Release i", "Release j"],
        [[m["id"], m["i"], m["j"], m.get("type", "Frame"), m["material"], m["section"], m.get("release_i", False), m.get("release_j", False)] for m in model["members"]],
    )
    write(
        "node_results.csv",
        ["Case", "Node", "UX [m]", "UZ [m]", "Rotation [rad]", "RX [kN]", "RZ [kN]", "MY [kN.m]"],
        [[case, nid, row["ux"], row["uz"], row["rotation"], row["Rx"], row["Rz"], row["My"]] for nid, row in data["nodes"].items()],
    )
    write(
        "member_extrema.csv",
        ["Case", "Member", "Quantity", "Type", "Value", "x [m]", "Side"],
        [[case, mid, quantity, kind, row["value"], row["x"], row["side"]]
         for mid, member in data["members"].items()
         for quantity, extrema in member["extrema"].items()
         for kind, row in extrema.items()],
    )
    write(
        "member_diagrams.csv",
        ["Case", "Member", "x [m]", "Side", "N [kN]", "V [kN]", "M [kN.m]", "d [m]", "UX [m]", "UZ [m]"],
        [[case, mid, row["x"], row["side"], row["N"], row["V"], row["M"], row["d"], row["ux"], row["uz"]]
         for mid, member in data["members"].items() for row in member["plot"]],
    )
    return paths


def _bounds(model):
    xs = [float(n["x"]) for n in model["nodes"]]
    zs = [float(n["z"]) for n in model["nodes"]]
    xmin, xmax = min(xs), max(xs)
    zmin, zmax = min(zs), max(zs)
    if xmax - xmin < 1e-9:
        xmax += 0.5; xmin -= 0.5
    if zmax - zmin < 1e-9:
        zmax += 0.5; zmin -= 0.5
    return xmin, xmax, zmin, zmax


def _xy_mapper(model, rect):
    xmin, xmax, zmin, zmax = _bounds(model)
    spanx, spanz = xmax - xmin, zmax - zmin
    sx = rect.width() / spanx
    sz = rect.height() / spanz
    scale = min(sx, sz) * 0.82
    cx = (xmin + xmax) / 2.0
    cz = (zmin + zmax) / 2.0
    rx = rect.center().x()
    ry = rect.center().y()
    def point(x, z):
        from PySide6.QtCore import QPointF
        return QPointF(rx + (x - cx) * scale, ry - (z - cz) * scale)
    return point, scale


def _draw_arrow(painter, a, b, color, width=2):
    from PySide6.QtCore import QPointF
    from PySide6.QtGui import QBrush, QColor, QPen, QPolygonF
    painter.setPen(QPen(QColor(color), width))
    painter.setBrush(QBrush(QColor(color)))
    painter.drawLine(a, b)
    dx, dy = b.x() - a.x(), b.y() - a.y()
    L = math.hypot(dx, dy)
    if L < 1e-6:
        return
    ux, uy = dx / L, dy / L
    nx, ny = -uy, ux
    size = 7.0
    p1 = QPointF(b.x() - ux * size + nx * size * 0.45, b.y() - uy * size + ny * size * 0.45)
    p2 = QPointF(b.x() - ux * size - nx * size * 0.45, b.y() - uy * size - ny * size * 0.45)
    painter.drawPolygon(QPolygonF([b, p1, p2]))


def _draw_moment(painter, p, sign, color, label=""):
    from PySide6.QtCore import QPointF, QRectF
    from PySide6.QtGui import QBrush, QColor, QPen, QPolygonF
    radius = 14.0
    rect = QRectF(p.x() - radius, p.y() - radius, radius * 2, radius * 2)
    painter.setPen(QPen(QColor(color), 1.5)); painter.setBrush(QBrush(QColor(color)))
    start = 35 * 16 if sign >= 0 else 145 * 16
    span = 285 * 16 if sign >= 0 else -285 * 16
    painter.drawArc(rect, start, span)
    angle = math.radians(320 if sign >= 0 else 220)
    tip = QPointF(p.x() + radius * math.cos(angle), p.y() - radius * math.sin(angle))
    tangent = angle - (math.pi / 2 if sign >= 0 else -math.pi / 2)
    ux, uy = math.cos(tangent), -math.sin(tangent)
    nx, ny = -uy, ux
    size = 6.0
    p1 = QPointF(tip.x() - ux * size + nx * size * 0.4, tip.y() - uy * size + ny * size * 0.4)
    p2 = QPointF(tip.x() - ux * size - nx * size * 0.4, tip.y() - uy * size - ny * size * 0.4)
    painter.drawPolygon(QPolygonF([tip, p1, p2]))
    if label:
        painter.drawText(QPointF(p.x() + 18, p.y() - 14), label)


def _draw_support(painter, p, support):
    from PySide6.QtCore import QPointF
    from PySide6.QtGui import QColor, QPen, QPolygonF
    painter.setPen(QPen(QColor("#34495e"), 1.5))
    x, y = p.x(), p.y()
    if support == "Fixed":
        painter.drawLine(QPointF(x - 8, y + 5), QPointF(x + 8, y + 5))
        for dx in (-6, -2, 2, 6):
            painter.drawLine(QPointF(x + dx, y + 5), QPointF(x + dx - 4, y + 11))
    elif support in ("Pin", "Roller"):
        painter.drawPolygon(QPolygonF([QPointF(x, y + 3), QPointF(x - 8, y + 14), QPointF(x + 8, y + 14)]))
        if support == "Roller":
            painter.drawEllipse(QPointF(x - 4, y + 18), 2.5, 2.5)
            painter.drawEllipse(QPointF(x + 4, y + 18), 2.5, 2.5)
    elif support == "RollerX":
        painter.drawPolygon(QPolygonF([QPointF(x + 3, y), QPointF(x + 14, y - 8), QPointF(x + 14, y + 8)]))
    elif support == "Spring":
        painter.drawText(QPointF(x + 5, y + 12), "SPR")


def _member_point(model, member, x):
    nodes = {n["id"]: n for n in model["nodes"]}
    a, b = nodes[member["i"]], nodes[member["j"]]
    L = math.hypot(b["x"] - a["x"], b["z"] - a["z"])
    t = 0.0 if L <= 1e-12 else float(x) / L
    return a["x"] + t * (b["x"] - a["x"]), a["z"] + t * (b["z"] - a["z"])


def _normal(model, member):
    nodes = {n["id"]: n for n in model["nodes"]}
    a, b = nodes[member["i"]], nodes[member["j"]]
    dx, dz = b["x"] - a["x"], b["z"] - a["z"]
    L = math.hypot(dx, dz)
    return -dz / L, dx / L


def _draw_model_page(painter, model, result, case, rect, title_text):
    from PySide6.QtCore import QPointF, QRectF, Qt
    from PySide6.QtGui import QColor, QFont, QPen
    point, _ = _xy_mapper(model, rect)
    nodes = {n["id"]: n for n in model["nodes"]}
    painter.setPen(QPen(QColor("#53616d"), 2))
    for m in model["members"]:
        a, b = nodes[m["i"]], nodes[m["j"]]
        pa, pb = point(a["x"], a["z"]), point(b["x"], b["z"])
        painter.drawLine(pa, pb)
        painter.drawText((pa + pb) / 2 + QPointF(5, -5), m["id"])
    for n in model["nodes"]:
        p = point(n["x"], n["z"])
        painter.drawEllipse(p, 3.0, 3.0)
        _draw_support(painter, p, n.get("support", "Free"))
        painter.drawText(p + QPointF(5, -7), n["id"])
    members = {m["id"]: m for m in model["members"]}
    for load in model.get("point_loads", []):
        f = _case_factor(model, case, load["case"])
        if abs(f) < 1e-12:
            continue
        if "node" in load:
            n = nodes[load["node"]]; base = point(n["x"], n["z"])
        else:
            x,z = _member_point(model, members[load["member"]], load["x"]); base = point(x,z)
        value = float(load["value"]) * f
        color = _case_color(model, load["case"])
        if load["direction"] == "FZ":
            tail = base + QPointF(0, -34 if value < 0 else 34)
            _draw_arrow(painter, tail, base, color, 1)
            painter.setPen(QPen(QColor(color), 1)); painter.drawText(base + QPointF(7, -7), f"FZ {value:.4g} kN")
        elif load["direction"] == "FX":
            tail = base + QPointF(-34 if value > 0 else 34, 0)
            _draw_arrow(painter, tail, base, color, 1)
            painter.setPen(QPen(QColor(color), 1)); painter.drawText(base + QPointF(7, -7), f"FX {value:.4g} kN")
        elif load["direction"] == "MY":
            _draw_moment(painter, base, 1.0 if value >= 0 else -1.0, color, f"MY {value:.4g} kN·m")

    for load in model.get("distributed_loads", []):
        f = _case_factor(model, case, load["case"])
        if abs(f) < 1e-12:
            continue
        member = members[load["member"]]
        x1 = float(load.get("x1", 0.0)); x2 = float(load.get("x2", 0.0))
        if x2 <= x1:
            continue
        w1 = float(load["w1"]) * f; w2 = float(load["w2"]) * f
        color = _case_color(model, load["case"])
        bases=[]; tails=[]
        peak=max(abs(w1),abs(w2),1e-12)
        for i in range(7):
            t=i/6.0; x=x1+(x2-x1)*t; value=w1+(w2-w1)*t
            wx,wz=_member_point(model,member,x); base=point(wx,wz)
            arrow=14.0+28.0*(abs(value)/peak)
            if load["direction"] == "FZ":
                tail=base+QPointF(0,-arrow if value<0 else arrow)
            else:
                tail=base+QPointF(-arrow if value>0 else arrow,0)
            bases.append(base); tails.append(tail); _draw_arrow(painter,tail,base,color,1)
        painter.setPen(QPen(QColor(color),1))
        for a,b in zip(tails,tails[1:]): painter.drawLine(a,b)
        label=f"{load['direction']} w={w1:.3g} kN/m" if abs(w1-w2)<1e-12 else f"{load['direction']} w={w1:.3g}->{w2:.3g} kN/m"
        painter.drawText(tails[len(tails)//2]+QPointF(5,-5),label)

    if model.get("self_weight"):
        sw_case=model.get("self_weight_case") or "DL"; f=_case_factor(model,case,sw_case)
        if abs(f)>1e-12:
            materials={row["id"]:row for row in model.get("materials",[])}
            sections={row["id"]:row for row in model.get("sections",[])}
            color=_case_color(model,sw_case,self_weight=True)
            for member in model.get("members",[]):
                rho=float(materials[member["material"]].get("rho",0.0)); area=float(sections[member["section"]]["A"])
                q=-rho*area*f
                L=math.hypot(nodes[member["j"]]["x"]-nodes[member["i"]]["x"],nodes[member["j"]]["z"]-nodes[member["i"]]["z"])
                for x in (0.2*L,0.5*L,0.8*L):
                    wx,wz=_member_point(model,member,x); base=point(wx,wz); tail=base+QPointF(0,-22)
                    _draw_arrow(painter,tail,base,color,1)

    painter.setFont(QFont(painter.font().family(), 10))
    painter.setPen(QPen(QColor("#1f2933"), 1))
    painter.drawText(QRectF(rect.left(), rect.top() - 24, rect.width(), 20), Qt.AlignmentFlag.AlignLeft, title_text)


def _draw_diagram_page(painter, model, result, case, quantity, rect):
    from PySide6.QtCore import QPointF, QRectF, Qt
    from PySide6.QtGui import QBrush, QColor, QFont, QPainterPath, QPen, QPolygonF
    point, scale_model = _xy_mapper(model, rect)
    data = result["cases"][case]
    members = {m["id"]: m for m in model["members"]}
    nodes = {n["id"]: n for n in model["nodes"]}
    painter.setPen(QPen(QColor("#6b7280"), 1.5))
    for m in model["members"]:
        a,b=nodes[m["i"]],nodes[m["j"]]
        painter.drawLine(point(a["x"],a["z"]), point(b["x"],b["z"]))
    if quantity == "Reaction":
        peak = max((max(abs(v["Rx"]), abs(v["Rz"])) for v in data["nodes"].values()), default=0.0)
        k = 48.0 / peak if peak > 1e-12 else 0.0
        for nid,v in data["nodes"].items():
            n=nodes[nid]; base=point(n["x"],n["z"])
            if abs(v["Rx"])>1e-12:
                tail=base+QPointF(-v["Rx"]*k,0); _draw_arrow(painter,tail,base,"#cf7f20",1)
            if abs(v["Rz"])>1e-12:
                tail=base+QPointF(0,v["Rz"]*k); _draw_arrow(painter,tail,base,"#cf7f20",1)
            if abs(v["Rx"])+abs(v["Rz"])+abs(v["My"])>1e-12:
                painter.drawText(base+QPointF(6,-7),f"Rx {v['Rx']:.3g}  Rz {v['Rz']:.3g}  My {v['My']:.3g}")
        return
    if quantity == "Deflection":
        peak = max((abs(p["d"]) for mr in data["members"].values() for p in mr["plot"]), default=0.0)
        xmin, xmax, zmin, zmax = _bounds(model)
        span = max(xmax - xmin, zmax - zmin, 1.0)
        k_world = 0.16 * span / peak if peak > 1e-12 else 0.0
        painter.setPen(QPen(QColor("#8b5cb8"),2))
        for mid,mr in data["members"].items():
            m=members[mid]; nx,nz=_normal(model,m); pts=[]
            for row in mr["plot"]:
                x,z=_member_point(model,m,row["x"])
                # Positive anaStruct transverse d is displayed opposite the local
                # normal, matching the engineering viewport convention.
                pts.append(point(x - nx*row["d"]*k_world, z - nz*row["d"]*k_world))
            for a,b in zip(pts,pts[1:]): painter.drawLine(a,b)
        return
    if quantity == "Deformed":
        peak = max((math.hypot(p["ux"],p["uz"]) for mr in data["members"].values() for p in mr["plot"]), default=0.0)
        xmin, xmax, zmin, zmax = _bounds(model)
        span = max(xmax - xmin, zmax - zmin, 1.0)
        k_world = 0.16 * span / peak if peak > 1e-12 else 0.0
        painter.setPen(QPen(QColor("#8b5cb8"),2))
        for mid,mr in data["members"].items():
            m=members[mid]; pts=[]
            for row in mr["plot"]:
                x,z=_member_point(model,m,row["x"])
                pts.append(point(x+row["ux"]*k_world,z+row["uz"]*k_world))
            for a,b in zip(pts,pts[1:]): painter.drawLine(a,b)
        return
    peak = max((abs(row[quantity]) for mr in data["members"].values() for row in mr["plot"]), default=0.0)
    amp = min(rect.width(),rect.height()) * 0.18 / peak if peak > 1e-12 else 0.0
    pos=QColor("#3b82f6");pos.setAlpha(70); neg=QColor("#ef4444");neg.setAlpha(70)
    line_color={"N":"#244a7c","V":"#236b48","M":"#8f3030"}[quantity]
    for mid,mr in data["members"].items():
        m=members[mid]; nx,nz=_normal(model,m)
        rows=mr["plot"]
        base=[]; curve=[]
        for row in rows:
            x,z=_member_point(model,m,row["x"]); bp=point(x,z)
            # amp is in page pixels; offset directly in page coordinates after mapping the member normal.
            cp=QPointF(bp.x()+nx*row[quantity]*amp, bp.y()-nz*row[quantity]*amp)
            base.append(bp); curve.append(cp)
        painter.setPen(QPen(Qt.PenStyle.NoPen))
        for i in range(len(rows)-1):
            v0,v1=float(rows[i][quantity]),float(rows[i+1][quantity])
            if abs(v0)<1e-14 and abs(v1)<1e-14: continue
            parts=[(0.0,1.0,1 if (v0+v1)>=0 else -1)]
            if v0*v1<0:
                t=abs(v0)/(abs(v0)+abs(v1)); parts=[(0.0,t,1 if v0>=0 else -1),(t,1.0,1 if v1>=0 else -1)]
            for t0,t1,sgn in parts:
                def lerp(a,b,t): return QPointF(a.x()+(b.x()-a.x())*t,a.y()+(b.y()-a.y())*t)
                poly=QPolygonF([lerp(base[i],base[i+1],t0),lerp(curve[i],curve[i+1],t0),lerp(curve[i],curve[i+1],t1),lerp(base[i],base[i+1],t1)])
                painter.setBrush(QBrush(pos if sgn>=0 else neg)); painter.drawPolygon(poly)
        painter.setBrush(QBrush())
        painter.setPen(QPen(QColor(line_color),2))
        for a,b in zip(curve,curve[1:]): painter.drawLine(a,b)
        ex=mr.get("extrema",{}).get(quantity,{})
        unit={"N":"kN","V":"kN","M":"kN·m"}[quantity]
        for kind in ("min","max"):
            if kind not in ex: continue
            row=ex[kind]; x,z=_member_point(model,m,row["x"]); bp=point(x,z)
            cp=QPointF(bp.x()+nx*row["value"]*amp,bp.y()-nz*row["value"]*amp)
            painter.setPen(QPen(QColor("#1f2933"),1)); painter.drawText(cp+QPointF(5,-5),f"{row['value']:.4g} {unit}")


def export_pdf(path, model, result, case=None, viewport_image=None, viewport_options=None):
    from PySide6.QtCore import QRectF, Qt
    from PySide6.QtGui import QFont, QPainter, QPageSize, QPdfWriter

    cases = [case] if case is not None else list(result.get("cases", {}))
    if not cases:
        raise ValueError("No analysis cases / combinations to export")
    for name in cases:
        if name not in result.get("cases", {}):
            raise ValueError(f"Unknown result case: {name}")

    writer = QPdfWriter(str(path))
    writer.setPageSize(QPageSize(QPageSize.PageSizeId.A4))
    writer.setResolution(96)
    painter = QPainter(writer)
    try:
        page_w, page_h = writer.width(), writer.height()
        margin = 48

        def title_at(y, text, size=16):
            font = QFont(); font.setPointSize(size); font.setBold(True); painter.setFont(font)
            painter.drawText(QRectF(margin, y, page_w - 2 * margin, 30), Qt.AlignmentFlag.AlignLeft, text)
            return y + 34

        def row_at(y, text, size=9, indent=0):
            font = QFont(); font.setPointSize(size); painter.setFont(font)
            painter.drawText(QRectF(margin + indent, y, page_w - 2 * margin - indent, 22), Qt.AlignmentFlag.AlignLeft, text)
            return y + 20

        # Cover / model overview.
        y = margin
        y = title_at(y, "GO 2D Structural — anaStruct Report", 17)
        y = row_at(y, f"Solver: {result.get('solver')} {result.get('solver_version')}")
        y = row_at(y, f"Cases / combinations: {', '.join(cases)}")
        y = row_at(y, f"Nodes: {len(model['nodes'])}    Members: {len(model['members'])}")
        y = row_at(y, "Analysis units: m, kN, kN·m")
        y = row_at(y, f"Coordinate mapping: {result.get('coordinate_map', '')}")
        y += 10
        graph = QRectF(margin, y + 20, page_w - 2 * margin, page_h - y - margin - 40)
        _draw_model_page(painter, model, result, cases[0], graph, "Analytical model + applied loads")

        # Capture the exact IngeTrazo viewport state when available. This gives
        # the report a visual record of what the engineer was reviewing.
        selected_view_case = (viewport_options or {}).get("case") or cases[0]
        active_only = bool((viewport_options or {}).get("active_only", True))
        if viewport_image is not None and not viewport_image.isNull():
            writer.newPage()
            painter.setFont(QFont(painter.font().family(), 14, QFont.Weight.Bold))
            painter.drawText(QRectF(margin, margin, page_w - 2 * margin, 26), Qt.AlignmentFlag.AlignLeft, "IngeTrazo viewport snapshot")
            painter.setFont(QFont(painter.font().family(), 9))
            diagram_name = (viewport_options or {}).get("diagram", "Model")
            painter.drawText(QRectF(margin, margin + 28, page_w - 2 * margin, 18), Qt.AlignmentFlag.AlignLeft, f"Case / combination: {selected_view_case}    Diagram: {diagram_name}")
            image_area = QRectF(margin, margin + 52, page_w - 2 * margin, page_h - 2 * margin - 150)
            painter.drawImage(_fit_image_rect(viewport_image, image_area), viewport_image)
            legend_rect = QRectF(margin, image_area.bottom() + 10, page_w - 2 * margin, 88)
            _draw_load_legend(painter, model, selected_view_case, legend_rect, active_only=active_only, options=viewport_options)

        for case_name in cases:
            data = result["cases"][case_name]
            # Case summary page.
            writer.newPage()
            y = margin
            y = title_at(y, f"Results summary — {case_name}", 15)
            y = title_at(y, "Support reactions", 11)
            for nid, values in data["nodes"].items():
                if abs(values["Rx"]) + abs(values["Rz"]) + abs(values["My"]) > 1e-9:
                    y = row_at(y, f"{nid}: Rx={values['Rx']:.5g} kN   Rz={values['Rz']:.5g} kN   My={values['My']:.5g} kN·m")
            y += 8
            y = title_at(y, "Member extrema", 11)
            units = {"N": "kN", "V": "kN", "M": "kN·m", "d": "m"}
            for mid, member in data["members"].items():
                y = row_at(y, mid, 9)
                for quantity, extrema in member["extrema"].items():
                    lo, hi = extrema["min"], extrema["max"]
                    y = row_at(y, f"{quantity}: min {lo['value']:.5g} {units[quantity]} @ {lo['x']:.4g} m | max {hi['value']:.5g} {units[quantity]} @ {hi['x']:.4g} m", 8, 12)
                    if y > page_h - margin - 80:
                        writer.newPage(); y = margin
                        y = title_at(y, f"Results summary — {case_name} (cont.)", 13)

            pages = [
                ("Analytical model + applied loads", "Model"),
                ("Axial force N", "N"),
                ("Shear force V", "V"),
                ("Bending moment M", "M"),
                ("Deflection", "Deflection"),
                ("Deformed shape", "Deformed"),
                ("Support reactions", "Reaction"),
            ]
            for heading, quantity in pages:
                writer.newPage()
                painter.setFont(QFont(painter.font().family(), 14, QFont.Weight.Bold))
                painter.drawText(QRectF(margin, margin, page_w - 2 * margin, 26), Qt.AlignmentFlag.AlignLeft, f"{heading} — {case_name}")
                graph_height = page_h - 2 * margin - (150 if quantity == "Model" else 70)
                graph = QRectF(margin, margin + 46, page_w - 2 * margin, graph_height)
                if quantity == "Model":
                    _draw_model_page(painter, model, result, case_name, graph, "Analytical model")
                    legend_rect = QRectF(margin, page_h - margin - 72, page_w - 2 * margin, 66)
                    _draw_load_legend(painter, model, case_name, legend_rect, active_only=True)
                else:
                    _draw_diagram_page(painter, model, result, case_name, quantity, graph)

        writer.newPage()
        y = margin
        y = title_at(y, "Scope / limitations", 13)
        y = row_at(y, "Linear elastic first-order 2D frame/truss analysis.")
        y = row_at(y, "No member capacity, nonlinear, P-Delta, shell/plate or code-compliance check.")
        y = row_at(y, "Engineering results are drafts and should be reviewed by a competent engineer before design decisions.")
    finally:
        painter.end()
    return str(path)

"""Read GO Factory v0.3.1 member metadata; no GO Factory import is required.

The bridge is deliberately read-only: it never alters scene.groups, steel meshes,
component instances, layers, colors or BIM metadata.
"""
from __future__ import annotations

import math
from .examples import factory_gable_demo
from .model import member_length, validate
from .sections import starter_sections
from .engineering_core import (
    CATALOG_VERSION, CatalogError, nominal_section_properties,
    section_record, catalog_info,
)

FACTORY_KEY = "go_factory_generator"
ALIGN_TOLERANCE_M = 1e-5
DEFAULT_EXAMPLE = "11 — Gable Frame from GO Factory"


class FactoryImportError(ValueError):
    """Factory model is absent, inconsistent or requires engineering input."""


def _point(raw, label):
    if not isinstance(raw, (list, tuple)) or len(raw) != 3:
        raise FactoryImportError(f"{label} must be an XYZ coordinate [m]")
    try:
        xyz = tuple(float(v) for v in raw)
    except (TypeError, ValueError) as exc:
        raise FactoryImportError(f"{label} has non-numeric coordinates") from exc
    if not all(math.isfinite(v) for v in xyz):
        raise FactoryImportError(f"{label} has non-finite coordinates")
    return xyz


def _close(a, b, tol=ALIGN_TOLERANCE_M):
    return math.dist(a, b) <= tol


def _cluster(values, tol=ALIGN_TOLERANCE_M):
    distinct = []
    for value in sorted(values):
        if not distinct or abs(value - distinct[-1]) > tol:
            distinct.append(value)
    return distinct


def members_from_scene(scene):
    """Return centerline metadata from the live IngeTrazo scene.

    GO Factory stores authoritative world coordinates under group.ext. No
    geometry traversal, mesh reconstruction, or undocumented APIs are used.
    """
    if scene is None:
        return []
    rows = []
    for group in getattr(scene, "groups", ()) or ():
        ext = getattr(group, "ext", None) or {}
        metadata = ext.get(FACTORY_KEY) if isinstance(ext, dict) else None
        if not isinstance(metadata, dict):
            continue
        if metadata.get("category") not in ("Column", "Rafter"):
            continue
        project = metadata.get("project")
        if not isinstance(project, str) or not project.strip():
            raise FactoryImportError("GO Factory member has no project name")
        catalog = catalog_info()
        remote_ver = metadata.get("section_catalog_version")
        remote_hash = metadata.get("section_catalog_sha256")
        if remote_ver and remote_ver != catalog["version"]:
            raise FactoryImportError(
                f"GO Factory member from catalog {remote_ver} differs from "
                f"GO anaStruct catalog {catalog['version']}; update both extensions"
            )
        if remote_hash and remote_hash != catalog["sha256"]:
            raise FactoryImportError(
                "GO Factory / GO anaStruct catalog checksum mismatch. "
                "Do not map this profile until both plugins use the same snapshot"
            )
        mark = metadata.get("mark", "?")
        a = _point(metadata.get("start"), f"GO Factory {mark}.start")
        b = _point(metadata.get("end"), f"GO Factory {mark}.end")
        if _close(a, b):
            raise FactoryImportError(f"GO Factory {mark} has a zero-length centerline")
        section = metadata.get("section")
        if not isinstance(section, str) or not section.strip():
            raise FactoryImportError(f"GO Factory {mark} is missing its section name")
        rows.append({
            "project": project.strip(), "category": metadata["category"],
            "section": section.strip(), "mark": str(mark), "start": a, "end": b,
            "catalog_version": remote_ver, "catalog_sha256": remote_hash,
        })
    return rows


def project_stations(rows):
    """Map project names to the transverse frame stations of planar members."""
    projects = {}
    for row in rows:
        a, b = row["start"], row["end"]
        if abs(a[1] - b[1]) <= ALIGN_TOLERANCE_M:
            projects.setdefault(row["project"], []).append((a[1] + b[1]) / 2)
    return {name: _cluster(stations) for name, stations in sorted(projects.items())}


def _at_station(rows, project, y):
    return [
        row for row in rows if row["project"] == project
        and abs(row["start"][1] - y) <= ALIGN_TOLERANCE_M
        and abs(row["end"][1] - y) <= ALIGN_TOLERANCE_M
    ]


def _geometry(rows, project, frame_y):
    chosen = _at_station(rows, project, frame_y)
    columns = [r for r in chosen if r["category"] == "Column"]
    rafters = [r for r in chosen if r["category"] == "Rafter"]
    if len(columns) != 2 or len(rafters) != 2:
        raise FactoryImportError(
            f"{project} at Y={frame_y:g} m: expected 2 columns and 2 rafters "
            f"for an unsupported-free gable portal; found {len(columns)} "
            f"columns and {len(rafters)} rafters. Center columns, trusses, "
            "hip/cross-gable and segmented roofs require a separate adapter."
        )
    standing = []
    for col in columns:
        a, b = sorted((col["start"], col["end"]), key=lambda p: p[2])
        if abs(a[0] - b[0]) > ALIGN_TOLERANCE_M:
            raise FactoryImportError("Skewed/non-vertical column not supported")
        standing.append((a, b, col))
    standing.sort(key=lambda r: r[0][0])
    (lb, le, left_col), (rb, re, right_col) = standing
    if re[0] - le[0] < ALIGN_TOLERANCE_M:
        raise FactoryImportError("Invalid/zero width portal")
    if not math.isclose(lb[2], rb[2], abs_tol=ALIGN_TOLERANCE_M):
        raise FactoryImportError("Factory column bases have different elevations")
    if not math.isclose(le[2], re[2], abs_tol=ALIGN_TOLERANCE_M):
        raise FactoryImportError("Factory eaves have different elevations")

    def rafter_from(eave):
        matching = [
            (row, row["end"] if _close(row["start"], eave)
             else row["start"])
            for row in rafters
            if _close(row["start"], eave) or _close(row["end"], eave)
        ]
        if len(matching) != 1:
            raise FactoryImportError("Cannot uniquely connect a rafter to the column eave")
        return matching[0]

    left_raf, left_peak = rafter_from(le)
    right_raf, right_peak = rafter_from(re)
    if left_raf is right_raf or not _close(left_peak, right_peak):
        raise FactoryImportError("Roof rafters do not meet at a shared ridge")
    ridge = tuple((a+b)/2 for a, b in zip(left_peak, right_peak))
    if not le[0] < ridge[0] < re[0] or ridge[2] <= max(le[2], re[2]):
        raise FactoryImportError("Ridge is not above and between the eaves")
    named = (("N1", lb), ("N2", le), ("N3", ridge), ("N4", re), ("N5", rb))
    source = (left_col, left_raf, right_raf, right_col)
    return named, source


def required_section_mappings(rows, project, frame_y):
    """Require explicit engineering choices for every factory section name."""
    _, source = _geometry(rows, project, frame_y)
    return sorted({row["section"] for row in source})


def _mapping_section(section_name, selection, available):
    """Return (analysis section ID, added row or None).

    GO Factory's sketch/catalog section name is not a validated engineering
    cross-section. Only an explicit nominal-preview axis selection permits
    generating A/Iz. Manual starter mapping is for preview and MUST be steel.
    """
    if isinstance(selection, str):
        # Old preview projects used plain analysis section IDs; preserve only
        # explicit steel mappings, never an RC substitution for a steel member.
        selection = {"mode": "manual_starter", "section": selection,
                     "acknowledged": True}
    if not isinstance(selection, dict) or selection.get("acknowledged") is not True:
        raise FactoryImportError(
            f"{section_name}: select a section and acknowledge that its "
            "properties are not verified for structural design"
        )
    mode = selection.get("mode")
    if mode == "go_core_nominal":
        axis = selection.get("axis")
        try:
            p = nominal_section_properties(
                section_name, axis=axis, acknowledge_unverified=True
            )
        except CatalogError as exc:
            raise FactoryImportError(str(exc)) from exc
        section_id = f"GOCORE:{section_name}:{axis}"
        return section_id, {
            "id": section_id, "A": p["A_m2"], "Iz": p["Iz_m4"],
            "kind": "Steel", "catalog_id": section_name,
            "catalog_version": CATALOG_VERSION, "bending_axis": axis,
            "Ix": p["Ix_m4"], "Iy": p["Iy_m4"],
            "property_status": "NOMINAL_GEOMETRY_ONLY",
            "verified": False,
        }
    if mode == "manual_starter":
        dest = selection.get("section")
        row = available.get(dest)
        if row is None or row.get("kind") != "Steel":
            raise FactoryImportError(
                f"{section_name}: mapping to {dest!r} is not a known Steel "
                "analysis section. RC section substitutions are prohibited."
            )
        return dest, None
    raise FactoryImportError(f"{section_name}: unsupported section mapping mode {mode!r}")


def build_analysis_from_factory(rows, project, frame_y, section_mapping=None,
                                support="Fixed"):
    """Build a planar GO Factory FEM frame from exact member centerlines.

    All nominal sections require explicit engineering approval for demonstration
    use. Source metadata is read-only. The selected world Y is a display
    placement and does not change the 2D FEM fingerprint.
    """
    frame_y = float(frame_y)
    if not math.isfinite(frame_y):
        raise FactoryImportError("Frame station must be finite")
    if support not in ("Fixed", "Pin"):
        raise FactoryImportError("Base restraint must be explicitly Fixed or Pin")
    named, sources = _geometry(rows, project, frame_y)
    section_mapping = section_mapping or {}
    available = {row["id"]: row for row in starter_sections()}
    model = factory_gable_demo()
    existing = {row["id"] for row in model["sections"]}
    section_ids = []
    for record in sources:
        section_name = record["section"]
        if section_name not in section_mapping:
            raise FactoryImportError(
                f"Section {section_name} requires a GO Core nominal-axis "
                "preview choice or a verified manual Steel section mapping"
            )
        sid, newrow = _mapping_section(section_name, section_mapping[section_name], available)
        if newrow is not None and sid not in existing:
            model["sections"].append(newrow)
            existing.add(sid)
        section_ids.append(sid)

    model["nodes"] = [
        {"id": name, "x": point[0], "z": point[2],
         "support": support if name in ("N1", "N5") else "Free"}
        for name, point in named
    ]
    for member, sid in zip(model["members"], section_ids):
        member["section"] = sid
    for load in model["distributed_loads"]:
        load["x2"] = member_length(
            model,
            next(m for m in model["members"] if m["id"] == load["member"]),
        )
    model = validate(model)

    # Independently compare each FEM member's world-space endpoints with the
    # original factory member endpoints (order may be reversed). This checks
    # endpoint mapping, NOT whether a user manually moved meshes afterwards.
    by_node = {row["id"]: row for row in model["nodes"]}
    errors = []
    for member, source in zip(model["members"], sources):
        one = by_node[member["i"]]
        two = by_node[member["j"]]
        p = (one["x"], frame_y, one["z"])
        q = (two["x"], frame_y, two["z"])
        a, b = source["start"], source["end"]
        errors.append(min(max(math.dist(p, a), math.dist(q, b)),
                          max(math.dist(p, b), math.dist(q, a))))
    err = max(errors)
    if err > ALIGN_TOLERANCE_M:
        raise FactoryImportError(
            f"Factory endpoint-to-analysis alignment error {err:g} m exceeds tolerance"
        )
    placement = {
        "enabled": True, "frame_y": frame_y, "project": project,
        "source": FACTORY_KEY, "frame_stations": project_stations(rows).get(project, [frame_y]),
        "alignment_error_m": err,
        "alignment_source": "factory-centerline-metadata",
        "markers": [[float(x), float(y), float(z)] for _, (x, y, z) in named],
        "section_mapping": dict(section_mapping),
        "catalog_version": CATALOG_VERSION,
        "catalog_sha256": catalog_info()["sha256"],
        "factory_metadata_catalog_pinned": all(
            source.get("catalog_sha256") == catalog_info()["sha256"]
            for source in sources
        ),
        "preview_unverified_properties": True,
    }
    return model, placement

"""Preserve user-authored FEM parameters during a geometry-equivalent factory import."""
from __future__ import annotations
import copy
import math
from .model import validate


class ReimportNeedsConfirmation(ValueError):
    pass


def preserve_analysis_edits(previous, imported, *, retain_sections=True,
                            tolerance=1e-5):
    """Preserve loads, combos, material edits and end releases for matching frame.

    World Y is presentation-only. Different XZ geometry or topology requires
    explicit user confirmation to reset; never silently shift a load location.
    Base restraints follow the explicit current Fixed/Pin selector.
    """
    if previous is None:
        return validate(imported)
    old, new = validate(previous), validate(imported)
    old_nodes = {row["id"]: row for row in old["nodes"]}
    new_nodes = {row["id"]: row for row in new["nodes"]}
    old_members = {row["id"]: row for row in old["members"]}
    new_members = {row["id"]: row for row in new["members"]}
    if set(old_nodes) != set(new_nodes) or set(old_members) != set(new_members):
        raise ReimportNeedsConfirmation("Factory frame node/member IDs changed; confirm replacing edited loads")
    for nid, current in new_nodes.items():
        prev = old_nodes[nid]
        if math.hypot(current["x"] - prev["x"], current["z"] - prev["z"]) > tolerance:
            raise ReimportNeedsConfirmation("Factory frame geometry changed; manually review/reset load positions")
    for mid, current in new_members.items():
        prev = old_members[mid]
        if (current["i"], current["j"], current.get("type", "Frame")) != (
            prev["i"], prev["j"], prev.get("type", "Frame")
        ):
            raise ReimportNeedsConfirmation("Factory frame connectivity changed; confirm replacing edited analysis")
    fresh = copy.deepcopy(new)
    for key in (
        "cases", "case_metadata", "combinations", "combination_metadata",
        "point_loads", "distributed_loads", "self_weight", "self_weight_case",
        "materials",
    ):
        if key in old:
            fresh[key] = copy.deepcopy(old[key])

    # Preserve material IDs, analytical section edits and connection releases.
    # A changed explicit catalog selection will intentionally take precedence.
    old_section_rows = {row["id"]: row for row in old["sections"]}
    section_rows = {row["id"]: row for row in fresh["sections"]}
    if retain_sections:
        section_rows.update(copy.deepcopy(old_section_rows))
    for row in fresh["members"]:
        before = old_members[row["id"]]
        for key in ("release_i", "release_j"):
            if key in before:
                row[key] = before[key]
        if retain_sections:
            row["section"] = before["section"]
        if before.get("material") in {m["id"] for m in fresh["materials"]}:
            row["material"] = before["material"]
    fresh["sections"] = list(section_rows.values())
    return validate(fresh)
